        for s in seps:
            if s>cur: out.append((cur,s)); cur=s+1
        if cur<n: out.append((cur,n))
        return out
    rows=ran(sr,0,H); cols=ran(scols,0,W)
    best=(-1,None)
    for (a,b) in rows:
        for (c,d) in cols:
            n=sum(1 for r in range(a,b) for q in range(c,d) if g[r][q]==marker)
            if n>best[0]: best=(n,(a,b,c,d))
